 std::function<void(bool)> onSequenceRequested;
 explicit KeyboardPanel(SynthProcessor& processor):p(processor),portamento(p),keyboard(p),pitch(p,true),mod(p,false){using namespace juce;setComponentID("performance-keyboard");addAndMakeVisible(portamento);for(auto* c:{(Component*)&keyboard,(Component*)&pitch,(Component*)&mod,(Component*)&octaveDown,(Component*)&octaveUp,(Component*)&octaveLabel,(Component*)&swingOn,(Component*)&rate,(Component*)&clipKeys,(Component*)&arpKeys})addAndMakeVisible(c);keyboard.setOctaveForMiddleC(4);keyboard.setKeyWidth(24);keyboard.setAvailableRange(0,127);keyboard.setScrollButtonsVisible(false);keyboard.setColour(MidiKeyboardComponent::whiteNoteColourId,nd::colour(Colour(0xffffffff)));keyboard.setColour(MidiKeyboardComponent::blackNoteColourId,nd::colour(Colour(0xff0c1620)));keyboard.setColour(MidiKeyboardComponent::keyDownOverlayColourId,nd::colour(Colour(NEXUM_UI_ACCENT)).withAlpha(.8f));keyboard.setColour(MidiKeyboardComponent::keySeparatorLineColourId,nd::colour(Colour(0xff344650)));keyboard.setColour(MidiKeyboardComponent::shadowColourId,Colours::transparentBlack);keyboard.setComponentID("piano-keys");
 bind(up,"pitchBendUp");bind(down,"pitchBendDown");bind(transpose,"transpose");bind(swing,"swingAmount");for(auto* range:{&up,&down}){range->setLookAndFeel(&bendTheme);range->setSliderStyle(Slider::IncDecButtons);range->setIncDecButtonsMode(Slider::incDecButtonsDraggable_Vertical);range->setTextBoxStyle(Slider::TextBoxLeft,false,29,24);}up.textFromValueFunction=[](double v){return "+"+String((int)v);};down.textFromValueFunction=[](double v){return "-"+String((int)v);};down.valueFromTextFunction=[](const String& s){return std::abs(s.getDoubleValue());};swing.textFromValueFunction=[](double v){return String(juce::roundToInt(v*100))+" %";};swing.valueFromTextFunction=[](const String& s){return s.getDoubleValue()/100;};transpose.textFromValueFunction=[](double v){return String((int)v)+" st";};for(auto* slider:{&up,&down,&transpose,&swing})slider->updateText();up.setTooltip("Pitch bend up: semitones");down.setTooltip("Pitch bend down: semitones");transpose.setTooltip("Transpose incoming MIDI and piano notes; held notes retain their original note-off mapping.");swing.setTooltip("Offbeat delay amount for the internal or imported arpeggiator. This does not quantize live MIDI.");
 octaveLabel.setFont(FontOptions(10.f,Font::bold));octaveLabel.setColour(Label::textColourId,nd::colour(Colour(0xff8ba0ae)));octaveLabel.setJustificationType(Justification::centred);octaveDown.onClick=[this]{p.set("keyboardOctave",p.value("keyboardOctave")-1);timerCallback();};octaveUp.onClick=[this]{p.set("keyboardOctave",p.value("keyboardOctave")+1);timerCallback();};octaveDown.setTooltip("Show one octave lower");octaveUp.setTooltip("Show one octave higher");swingOn.setClickingTogglesState(true);swingAttachment=std::make_unique<AudioProcessorValueTreeState::ButtonAttachment>(p.state,"swingEnabled",swingOn);rate.addItemList({"1/64","1/32","1/16","1/8","1/4","1/2","1 bar"},1);clipKeys.onEdit=[this]{if(onSequenceRequested)onSequenceRequested(false);};arpKeys.onEdit=[this]{if(onSequenceRequested)onSequenceRequested(true);};rate.setTooltip("Arpeggiator rate for the selected pattern");timerCallback();startTimerHz(25);}
